(function(root){'use strict';
function validDay(day){try{return typeof day==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(day)&&day>='0001-01-01'&&new Date(day+'T00:00:00Z').toISOString().slice(0,10)===day;}catch{return false;}}
function range(from,to){if(!validDay(from)||!validDay(to)||from>to||(Date.parse(to+'T00:00:00Z')-Date.parse(from+'T00:00:00Z'))/86400000>365)throw Error('ماوەیەکی دروست هەڵبژێرە؛ زۆرترین ماوە ٣٦٦ ڕۆژە.');}
function integer(value){if(typeof value!=='string'||!/^\d+$/.test(value))throw Error('بڕی ڕاپۆرت نادروستە.');return BigInt(value);}
function money(value){return new Intl.NumberFormat('en-US').format(integer(value));}
function quantity(value){const n=integer(value),fraction=String(n%1000n).padStart(3,'0').replace(/0+$/,'');return new Intl.NumberFormat('en-US').format(n/1000n)+(fraction?'.'+fraction:'');}
function rawQuantity(value){const n=integer(value),fraction=String(n%1000n).padStart(3,'0').replace(/0+$/,'');return String(n/1000n)+(fraction?'.'+fraction:'');}
function validate(data,from,to){range(from,to);if(data?.from!==from||data.to!==to||data.timezone!=='Asia/Baghdad'||data.currency!=='IQD'||!Number.isFinite(Date.parse(data.generated_at))||!Array.isArray(data.rows)||data.count!==data.rows.length||data.count>5000)throw Error('وەڵامی ڕاپۆرت تەواو نییە.');const s=data.summary,values={};for(const k of ['receipt_count','tracked_count','untracked_count','total','paid','debt_added','untracked_total'])values[k]=integer(s?.[k]);if(values.receipt_count!==values.tracked_count+values.untracked_count||values.total!==values.paid+values.debt_added+values.untracked_total)throw Error('کۆی حسابی کڕین یەک ناگرێتەوە.');let total=0n;const seen=new Set();for(const row of data.rows){if(typeof row.product_id!=='string'||! /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(row.product_id)||seen.has(row.product_id)||typeof row.name!=='string'||!row.name||!(row.barcode===null||typeof row.barcode==='string')||!Number.isFinite(Date.parse(row.last_purchase_at))||integer(row.quantity_units)<=0n||integer(row.receipt_count)<1n||integer(row.receipt_count)>values.receipt_count)throw Error('ڕیزی کاڵای ڕاپۆرت نادروستە.');seen.add(row.product_id);total+=integer(row.total);}if(total!==values.total||(data.count===0)!==(values.receipt_count===0n))throw Error('کۆی کاڵا و پسوولەکان یەک ناگرێتەوە.');return data;}
function csv(data,escape){const rows=[['لە ڕۆژی','تا ڕۆژی','کاتی ڕاپۆرت','ناسنامەی کاڵا','ناوی کاڵا','بارکۆد','بڕی کڕدراو / یەکە','تێچووی کڕین / دیناری عێراقی','ژمارەی پسوولە','کۆتا کڕین'],...data.rows.map(r=>[data.from,data.to,data.generated_at,r.product_id,r.name,r.barcode,rawQuantity(r.quantity_units),r.total,r.receipt_count,r.last_purchase_at])];return '\ufeff'+rows.map(r=>r.map(escape).join(',')).join('\r\n')+'\r\n';}
root.PurchaseReportMath={range,validDay,integer,money,quantity,validate,csv};if(typeof module==='object'&&module.exports)module.exports=root.PurchaseReportMath;
})(globalThis);
